function economy(a,key){if(a==='buy'){const c=CROPS[key];if(!c||state.coins<c.cost)return '金币不够啦。';if(key==='sunflower'&&seasonAt(state.day).key!=='summer')return '向日葵种子只在夏季集市供应。';state.coins-=c.cost;state.seeds[key]++;return '买到一份'+c.name+'种子。'}if(a==='can-up'){if(state.can===2)return '水壶已经升满。';const price=[90,220][state.can];if(state.coins<price)return `需要 ${price} 金币。`;state.coins-=price;state.can++;state.water=maxWater();return '水壶升级！现在一次能浇 '+[1,3,6][state.can]+' 块田。'}if(a==='expand'){if(state.plots.length===24)return '农田已经全部开放。';const price=state.plots.length===6?160:420;if(state.coins<price)return `需要 ${price} 金币。`;state.coins-=price;const target=state.plots.length===6?12:24;while(state.plots.length<target)state.plots.push(emptyPlot());return '新的农田开放啦。'}if(a==='house-up'){if(state.house===2)return '小屋已经升满。';const price=[200,450][state.house];if(state.coins<price)return `需要 ${price} 金币。`;state.coins-=price;state.house++;return '小屋升级完成！新增花园装饰，体力上限提升到 '+maxEnergy()+'。'}if(a==='request'){const q=request();if(state.requestDay===state.day)return '今天已经交付过啦。';if(state.stock[q.crop]<q.count)return '还没有足够的委托物品。';state.stock[q.crop]-=q.count;state.coins+=q.coins;state.seeds[q.seed]++;state.requestDay=state.day;state.requests++;state.decor=Math.min(3,Math.floor(state.requests/3));return `委托完成！获得 ${q.coins} 金币和 1 份${CROPS[q.seed].name}种子。${state.requests%3===0?'庭院新增了花簇装饰！':''}`}return ''}

