function frame(t){const dt=Math.min(.04,(t-previous)/1000);previous=t;moving=false;if(ready&&$('loading').hidden&&$('modal').hidden){let dx=Number(keys.has('right'))-Number(keys.has('left')),dy=Number(keys.has('down'))-Number(keys.has('up'));const len=Math.hypot(dx,dy);if(len){stopWalking();facing=dx?(dx<0?'west':'east'):(dy<0?'north':'south');const x=state.x,y=state.y;dx=dx/len*170*dt;dy=dy/len*170*dt;if(passable(state.x+dx,state.y))state.x+=dx;if(passable(state.x,state.y+dy))state.y+=dy;moving=x!==state.x||y!==state.y}else advanceWalk(dt)}if(moving&&t-lastSaved>1600){save();lastSaved=t}paint(t);requestAnimationFrame(frame)}hud();if(!storageOK)$('save-state').textContent='自动保存不可用，请在「存档」中导出备份。';requestAnimationFrame(frame);

