function flexSprite(im,f,x,y,w,h,t,phase=0,flex=.75,amplitude=1.4){if(!im?.width)return;const z=Math.min(w/f[2],h/f[3]),dw=f[2]*z,dh=f[3]*z,step=Math.ceil(f[3]/16);for(let sy=0;sy<f[3];sy+=step){const sh=Math.min(step,f[3]-sy),fraction=sy/f[3],weight=Math.pow(Math.max(0,1-fraction/flex),1.6),dx=Math.sin(t*.0012+phase+fraction*.8)*amplitude*weight;ctx.drawImage(im,f[0],f[1]+sy,f[2],sh,x-dw/2+dx,y-dh+sy*z,dw,sh*z+.35)}}
function paintCrop(p,stage,x,y,t,phase){let im,f,w=108,h=[26,44,76,90][stage];if(p.crop==='carrot'){im=images.atlas;f=ATLAS[[6,7,8,9][stage]];w=110;h=[24,37,63,75][stage]}else if(p.crop==='sunflower'){im=images.sunflower;f=SUNFLOWERFRAMES[stage];h=[28,48,79,112][stage]}else if(CROPS[p.crop].sheet!==undefined){im=images.newCrops;f=NEWCROPFRAMES[CROPS[p.crop].sheet*4+stage];h=[26,48,p.crop==='cabbage'?62:90,p.crop==='cabbage'?76:108][stage]}else {im=images.crops;f=CROPFRAMES[{berry:0,pumpkin:4,orange:8}[p.crop]+stage];h=p.crop==='orange'?[25,45,100,125][stage]:[25,40,65,77][stage]}flexSprite(im,f,x,y,w,h,t,phase*1.3,.72,stage?1.4:0)}
