function paintLocalLights(t){const darkness=sceneLight(state.minute).night,strength=indoor()?.11+darkness*.8:darkness*1.7;if(!strength)return;ctx.save();ctx.scale(zoom,zoom);ctx.translate(-camX,-camY);ctx.globalCompositeOperation='screen';for(const [x,y,r] of localLightPoints()){const flicker=1+Math.sin(t*.003+x)*.025,g=ctx.createRadialGradient(x,y,2,x,y,r*flicker);g.addColorStop(0,`rgba(255,207,110,${Math.min(.8,strength*.95)})`);g.addColorStop(.25,`rgba(255,184,73,${strength*.33})`);g.addColorStop(1,'rgba(255,173,66,0)');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}ctx.restore()}

