/* 橘子岛午后 — original 16-bar miniature, 80 BPM, softly synthesized offline. */
(()=>{
const button=document.getElementById('music-toggle'),volume=document.getElementById('music-volume');
const PREF='lulu-island-music-v1';let enabled=true,level=.3;
try{const p=JSON.parse(localStorage.getItem(PREF)||'null');if(p){enabled=p.enabled!==false;if(Number.isFinite(p.volume))level=Math.max(0,Math.min(.7,p.volume))}}catch{}
volume.value=String(Math.round(level*100));let context,master,bus,timer=null,unlocked=false,step=0,next=0,inFlight=false;
const voices=new Set(),beat=60/80;
const chords=[[48,52,55,59],[45,48,52,55],[41,45,48,52],[43,47,50,57],[48,52,55,59],[45,48,52,55],[41,45,48,52],[43,47,50,55],[48,52,55,59],[45,48,52,55],[41,45,48,52],[43,47,50,57],[41,45,48,52],[43,47,50,55],[48,52,55,59],[48,52,55,59]];
const tune=[[76,null,79,76,74,null,72,null],[72,null,76,79,76,null,69,null],[69,null,72,76,74,72,69,null],[71,null,74,79,77,null,74,null],[76,79,81,null,79,76,74,null],[72,null,76,79,81,null,79,76],[77,null,76,72,69,null,72,null],[74,null,71,67,72,null,null,null],[79,null,76,79,84,null,81,79],[81,null,79,76,72,null,69,null],[77,null,76,72,76,null,77,null],[79,null,77,74,71,null,74,null],[77,null,76,72,69,null,72,76],[74,null,71,67,71,null,74,null],[76,null,79,76,72,null,74,null],[72,null,null,null,null,null,null,null]];
function save(){try{localStorage.setItem(PREF,JSON.stringify({enabled,volume:level}))}catch{}}
function label(){button.textContent=!enabled?'♫ 音乐：关':context?.state==='running'?'♫ 音乐：开':'♫ 音乐：待播放';button.setAttribute('aria-pressed',String(enabled));button.title='橘子岛午后 · 点击切换背景音乐'}
function create(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){button.textContent='音乐暂不可用';button.disabled=true;return false}context=new AC();master=context.createGain();master.gain.value=level;const filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=2600;const compressor=context.createDynamicsCompressor();compressor.threshold.value=-18;compressor.ratio.value=3;bus=context.createGain();bus.gain.value=.6;bus.connect(filter);filter.connect(compressor);compressor.connect(master);master.connect(context.destination);const echo=context.createDelay(1);echo.delayTime.value=beat*.75;const wet=context.createGain();wet.gain.value=.13;filter.connect(echo);echo.connect(wet);wet.connect(master);context.onstatechange=label;return true}
function note(midi,time,duration,amplitude,type='sine',pad=false){const o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.value=440*Math.pow(2,(midi-69)/12);const start=.0001;g.gain.setValueAtTime(start,time);g.gain.exponentialRampToValueAtTime(amplitude,time+(pad?.65:.018));g.gain.exponentialRampToValueAtTime(start,time+duration);o.connect(g);g.connect(bus);o.start(time);o.stop(time+duration+.03);voices.add(o);o.onended=()=>{voices.delete(o);o.disconnect();g.disconnect()}}
function schedule(){if(context.state!=='running'||!enabled||document.hidden)return;if(next<context.currentTime-.2)next=context.currentTime+.08;while(next<context.currentTime+.18){const bar=Math.floor(step/8)%16,k=step%8,c=chords[bar],m=tune[bar][k];if(k===0){for(const n of c)note(n+12,next,beat*4.8,.018,'sine',true);note(c[0]-12,next,beat*2.6,.055,'sine')}if(k===4)note(c[2]-12,next,beat*1.8,.03);const arpeggio=c[[0,2,1,3,0,2,1,2][k]]+12;note(arpeggio,next,beat*.75,.021,'triangle');if(m!==null){note(m,next,beat*1.65,.054);note(m+12,next,.18,.007)}step=(step+1)%128;next+=beat/2}}
function stop(){if(timer!==null){clearInterval(timer);timer=null}for(const o of voices){try{o.stop()}catch{}}voices.clear();if(context&&context.state==='running')context.suspend().catch(()=>{});label()}
async function start(){if(!enabled||document.hidden||inFlight)return;if(!context&&!create())return;inFlight=true;try{await context.resume();unlocked=true;if(enabled&&!document.hidden&&context.state==='running'){if(timer===null){next=context.currentTime+.08;schedule();timer=setInterval(schedule,60)}}else stop()}catch{button.title='轻点音乐按钮开始播放'}finally{inFlight=false;label()}}
function gesture(e){if(e.target.closest?.('.music-controls'))return;if(enabled)start()}
document.addEventListener('pointerdown',gesture,{passive:true});document.addEventListener('keydown',gesture);
button.addEventListener('click',()=>{if(enabled&&!unlocked){start();return}enabled=!enabled;save();if(enabled)start();else stop();label()});volume.addEventListener('input',()=>{level=Number(volume.value)/100;if(master)master.gain.setTargetAtTime(level,context.currentTime,.08);save()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(unlocked&&enabled)start()});window.addEventListener('pagehide',stop);window.addEventListener('blur',stop);window.addEventListener('focus',()=>{if(unlocked&&enabled)start()});label();
})();
